-- =====================================================
-- Verification Query
-- =====================================================
SELECT 
  data_source,
  business_type,
  tier,
  COUNT(*) as count
FROM businesses 
WHERE created_at >= '2025-08-18T20:01:06.205Z'::timestamp - interval '1 minute'
GROUP BY data_source, business_type, tier
ORDER BY data_source, business_type, tier;

-- Final count
SELECT COUNT(*) as total_businesses FROM businesses;
